prices = {"apple": 1, "pear": 2}

def price_of(item):
    try:
        value = prices[item]
    except KeyError:
        print(f"{item} is not on the menu.")
    else:
        print(f"{item} costs {value}.")

price_of("apple")
price_of("kiwi")

